export interface GantryReading {
  gantryId: string;
  laneId: number;
  plate: Plate;
  /** Camera confidence in [0, 1]. */
  confidence: number;
  at: number;
  vehicleClass: VehicleClass;
}

constructor(
  readonly id: string,
  readonly plate: Plate,
  private readonly ledger: Ledger,
  private readonly flags: FeatureFlags,
) {}

export class Ledger {
  private readonly entries: LedgerEntry[] = [];
  private readonly maxRetries = 3;

  post(sessionId: string, amountPaise: number): void {
    if (amountPaise <= 0) throw new Error('amount must be positive');
    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
      if (this.tryWrite({ sessionId, amountPaise, at: Date.now() })) return;
    }
    throw new Error(`ledger post failed after ${this.maxRetries} retries`);
  }

  private tryWrite(e: LedgerEntry): boolean {
    this.entries.push(e);
    return true;
  }

  /** Removes and returns every entry (settlement takes ownership). */
  drain(): LedgerEntry[] {
    return this.entries.splice(0, this.entries.length);
  }

  total(): number {
    return this.entries.reduce((a, e) => a + e.amountPaise, 0);
  }
}

export class Gantry {
  private readonly lanes = new Map<number, Lane>();

  constructor(readonly id: string, readonly plazaId: string, laneCount: number) {
    for (let i = 1; i <= laneCount; i++) this.lanes.set(i, new Lane(id, i));
  }

  lane(id: number): Lane {
    const l = this.lanes.get(id);
    if (!l) throw new Error(`gantry ${this.id} has no lane ${id}`);
    return l;
  }

  ingest(r: GantryReading): void {
    this.lane(r.laneId).record(r);
  }

  healthyLanes(now: number): number[] {
    return [...this.lanes.values()].filter((l) => l.isHealthy(now)).map((l) => l.id);
  }
}

/** One ANPR read from a gantry camera. */
export interface GantryReading {
  gantryId: string
  laneId: number
  plate: Plate
  /** Camera confidence in [0, 1]. */
  confidence: number
  at: number
  vehicleClass: VehicleClass
}
export type VehicleClass = 'car' | 'lcv' | 'bus' | 'truck' | 'multi-axle';
/** Reads below this confidence go to manual review instead of auto-charging. */
export const MIN_CONFIDENCE
export function isTrusted(r: GantryReading): boolean

export interface LedgerEntry {
  sessionId: string
  amountPaise: number
  at: number
}
/** In-memory ledger with retry-aware posting; real one talks to the settlement service. */
export class Ledger {
  private readonly entries: LedgerEntry[] = []
  private readonly maxRetries = 3
  post(sessionId: string, amountPaise: number): void
  private tryWrite(e: LedgerEntry): boolean
  /** Removes and returns every entry (settlement takes ownership). */
  drain(): LedgerEntry[]
  total(): number
}

/** Port to the acquiring bank's settlement API. */
export interface BankGateway {
  submit(batch: SettlementBatch): Promise<{ accepted: boolean; reference?: string; reason?: string }>
}
/** In-memory gateway used in tests and the demo. */
export class FakeBank implements BankGateway {
  readonly submitted: SettlementBatch[] = []
  constructor(private readonly rejectOver = Number.POSITIVE_INFINITY)
  async submit(batch: SettlementBatch)
}

/** Adjacent lanes often read the same vehicle twice. Reads of the same plate at the same gantry within */
export class ReadingDeduper {
  private readonly recent = new Map<string, GantryReading>()
  constructor(private readonly windowMs = 2_000)
  /** Returns the reading to keep, or undefined when it duplicates a better recent read. */
  accept(r: GantryReading): GantryReading | undefined
  prune(now: number): void
}

export function nextId(prefix: string): string {
  counter += 1;
  return `${prefix}-${counter}`;
}

export type SessionState = 'open' | 'closed' | 'disputed';
/** One vehicle passage through a multi-lane free-flow gantry. */
export class TollSession {
  state: SessionState = 'open'
  readonly openedAt = Date.now()
  closedAt?: number
  constructor( readonly id: string, readonly plate: Plate, private readonly ledger: Ledger, private readonly flags: FeatureFlags, )
  /** Closes the session and posts the charge; a disputed plate never charges. */
  close(amountPaise: number): void
  durationMs(): number
}

/** A gantry spanning several lanes at one plaza. */
export class Gantry {
  private readonly lanes = new Map<number, Lane>()
  constructor(readonly id: string, readonly plazaId: string, laneCount: number)
  lane(id: number): Lane
  ingest(r: GantryReading): void
  healthyLanes(now: number): number[]
}

let counter
/** Monotonic, process-unique ids with a readable prefix (`ses-1`, `tx-2`). */
export function nextId(prefix: string): string
/** Resets the counter; tests only. */
export function resetIds(): void

/** A settlement batch sent to the acquiring bank. */
export interface SettlementBatch {
  id: string
  entries: LedgerEntry[]
  totalPaise: number
  createdAt: number
}
/** Groups entries into batches of at most `maxEntries`, preserving order. */
export function makeBatches(idPrefix: string, entries: readonly LedgerEntry[], maxEntries: number, now: number): SettlementBatch[]

export type FlagName = 'charge-on-close' | 'strict-checksum' | 'dispute-queue';
/** Operator-controlled feature flags, loaded from the environment at boot. */
export class FeatureFlags {
  private readonly enabled = new Set<FlagName>()
  constructor(initial: readonly FlagName[] = ['charge-on-close'])
  isEnabled(flag: FlagName): boolean
  set(flag: FlagName, on: boolean): void
  static fromEnv(env: Record<string, string | undefined>): FeatureFlags
}

/** Turns gantry readings into charged sessions: dedupe → trust check → price → close → notify. */
export class PassageProcessor {
  private readonly deduper = new ReadingDeduper()
  readonly manualReview: GantryReading[] = []
  constructor( private readonly store: SessionStore, private readonly ledger: Ledger, private readonly pricing: PricingEngine, private readonly flags: FeatureFlags, private readonly notifier: Notifier, private readonly plazaId: string, )
  async process(raw: GantryReading): Promise<TollSession | undefined>
}
